// Python float repr()/str() formatting.
//
// CPython renders a double with the shortest decimal digit string that round-trips
// (David Gay / "mode 0" dtoa), then formats it in fixed or exponential notation
// according to `decpt <= -4 || decpt > 16`, where the value is 0.<digits> * 10**decpt.
// JavaScript's Number#toExponential() (no argument) yields exactly the same shortest
// round-tripping digits, so we borrow them and re-format per CPython's rules.

/**
 * Split a finite, non-zero double into its shortest round-tripping decimal form.
 * @returns {{digits: string, decpt: number}} value === 0.<digits> * 10**decpt
 */
function shortestDigits(x) {
  // e.g. 1.2345e+17 -> mantissa "1.2345", exponent 17
  const [mantissa, exponent] = Math.abs(x).toExponential().split('e');
  const digits = mantissa.replace('.', '');
  return { digits, decpt: Number(exponent) + 1 };
}

function formatExponent(exp) {
  const sign = exp < 0 ? '-' : '+';
  const abs = String(Math.abs(exp));
  return `e${sign}${abs.length < 2 ? '0' + abs : abs}`;
}

/**
 * repr() of a Python float. Also what str() produces in Python 3.
 * @param {number} x a JS double standing in for a Python float
 * @returns {string}
 */
export function floatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  // Object.is distinguishes -0.0, which Python reprs as "-0.0".
  const negative = x < 0 || Object.is(x, -0);
  const body = x === 0 ? '0.0' : formatMagnitude(shortestDigits(x));
  return negative ? '-' + body : body;
}

function formatMagnitude({ digits, decpt }) {
  if (decpt <= -4 || decpt > 16) {
    // Exponential notation: one digit before the point, no gratuitous ".0".
    const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits[0];
    return mantissa + formatExponent(decpt - 1);
  }
  if (decpt <= 0) return '0.' + '0'.repeat(-decpt) + digits;
  if (decpt >= digits.length) return digits + '0'.repeat(decpt - digits.length) + '.0';
  return digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

