// Python repr() for the JSON value model used throughout this port.
//
// Value model (chosen so that Python's int/float split and dict ordering survive):
//   Python None   -> null                Python str  -> string
//   Python bool   -> boolean             Python list -> Array
//   Python int    -> BigInt              Python dict -> Map (insertion-ordered, string keys)
//   Python float  -> number
//
// See ./value.mjs for the predicates that go with the model.

import { floatRepr } from './float.mjs';

// Python escapes any code point that is not "printable": everything in the
// general categories Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs -- except U+0020, which is
// printable. The engine's own Unicode tables give us this for free.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

function hexEscape(codePoint) {
  if (codePoint < 0x100) return '\\x' + codePoint.toString(16).padStart(2, '0');
  if (codePoint < 0x10000) return '\\u' + codePoint.toString(16).padStart(4, '0');
  return '\\U' + codePoint.toString(16).padStart(8, '0');
}

/**
 * repr() of a Python str: single quotes by default, double quotes when the
 * string contains a single quote but no double quote.
 * @param {string} s
 * @returns {string}
 */
export function strRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  // Iterate by code point: astral characters are one character to Python.
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x7f) out += cp < 0x20 ? hexEscape(cp) : ch;
    else out += isPrintable(cp) ? ch : hexEscape(cp);
  }
  return out + quote;
}

/**
 * repr() of any value in the model above.
 * @param {*} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  switch (typeof value) {
    case 'bigint': return value.toString();
    case 'number': return floatRepr(value);
    case 'string': return strRepr(value);
  }
  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
  if (value instanceof Map) {
    const items = [];
    for (const [k, v] of value) items.push(`${pyRepr(k)}: ${pyRepr(v)}`);
    return '{' + items.join(', ') + '}';
  }
  // Not reachable for JSON-sourced data; kept so a bug shows up as text, not a crash.
  return String(value);
}

/**
 * ", ".join(repr(x) for x in values) -- the shape most jsonschema messages use.
 * @param {Iterable<*>} values
 * @returns {string}
 */
export function reprJoin(values) {
  return [...values].map(pyRepr).join(', ');
}

