// A port of Python's json.loads (the strict C scanner's accepted grammar).
//
// Differences from JSON.parse that are observable through this program:
//   * NaN / Infinity / -Infinity are accepted.
//   * Integers stay exact and stay integers: 1 is an int, 1.0 and 1e2 are floats.
//   * Objects keep insertion order, and a repeated key updates in place rather
//     than moving to the end.
//   * Lone surrogates from \uXXXX escapes are preserved.
//   * Nesting deeper than the interpreter's recursion limit raises RecursionError.

import { PyJSONDecodeError, PyRecursionError } from './exceptions.mjs';

// CPython's default recursion limit is 1000 frames; the scanner burns a couple of
// frames per nesting level and starts from a non-empty stack.
const MAX_DEPTH = 990;

const WHITESPACE = new Set([' ', '\t', '\n', '\r']);

const ESCAPES = new Map([
  ['"', '"'], ['\\', '\\'], ['/', '/'], ['b', '\b'],
  ['f', '\f'], ['n', '\n'], ['r', '\r'], ['t', '\t'],
]);

const NUMBER_RE = /(-?(?:0|[1-9]\d*))(\.\d+)?([eE][-+]?\d+)?/y;

class Decoder {
  constructor(text) {
    this.s = text;
    this.i = 0;
  }

  error(msg, pos = this.i) {
    throw new PyJSONDecodeError(msg, this.s, pos);
  }

  skipWhitespace() {
    while (this.i < this.s.length && WHITESPACE.has(this.s[this.i])) this.i++;
  }

  decode() {
    this.skipWhitespace();
    const value = this.scanValue(0);
    this.skipWhitespace();
    if (this.i !== this.s.length) this.error('Extra data');
    return value;
  }

  scanValue(depth) {
    if (depth > MAX_DEPTH) throw new PyRecursionError('maximum recursion depth exceeded while decoding a JSON object from a string');
    const s = this.s;
    const ch = s[this.i];
    if (ch === undefined) this.error('Expecting value');
    if (ch === '"') return this.scanString();
    if (ch === '{') return this.scanObject(depth + 1);
    if (ch === '[') return this.scanArray(depth + 1);
    if (s.startsWith('null', this.i)) { this.i += 4; return null; }
    if (s.startsWith('true', this.i)) { this.i += 4; return true; }
    if (s.startsWith('false', this.i)) { this.i += 5; return false; }
    if (s.startsWith('NaN', this.i)) { this.i += 3; return NaN; }
    if (s.startsWith('Infinity', this.i)) { this.i += 8; return Infinity; }
    if (s.startsWith('-Infinity', this.i)) { this.i += 9; return -Infinity; }

    NUMBER_RE.lastIndex = this.i;
    const m = NUMBER_RE.exec(s);
    if (m && m[0] !== '') {
      this.i = NUMBER_RE.lastIndex;
      const [, integer, frac, exp] = m;
      // A fraction or an exponent makes it a float; otherwise it is an exact int.
      return frac || exp ? Number(m[0]) : BigInt(integer);
    }
    this.error('Expecting value');
  }

  scanString() {
    const s = this.s;
    const start = this.i;
    this.i++; // opening quote
    let out = '';
    for (;;) {
      const ch = s[this.i];
      if (ch === undefined) this.error('Unterminated string starting at', start);
      if (ch === '"') { this.i++; return out; }
      if (ch === '\\') {
        this.i++;
        const esc = s[this.i];
        if (esc === undefined) this.error('Unterminated string starting at', start);
        if (esc === 'u') {
          out += this.scanUnicodeEscape();
          continue;
        }
        const simple = ESCAPES.get(esc);
        if (simple === undefined) this.error(`Invalid \\escape: ${JSON.stringify(esc)}`, this.i - 1);
        out += simple;
        this.i++;
        continue;
      }
      if (ch < ' ') {
        this.error(`Invalid control character ${JSON.stringify(ch)} at`, this.i);
      }
      out += ch;
      this.i++;
    }
  }

  /** Reads one \uXXXX (already positioned on the 'u'), joining a valid surrogate pair. */
  scanUnicodeEscape() {
    const first = this.readHex4();
    if (first >= 0xd800 && first <= 0xdbff && this.s.startsWith('\\u', this.i)) {
      const save = this.i;
      this.i++; // onto the 'u'
      const second = this.readHex4();
      if (second >= 0xdc00 && second <= 0xdfff) {
        return String.fromCharCode(first, second);
      }
      this.i = save; // not a low surrogate: leave it for the next iteration
    }
    return String.fromCharCode(first);
  }

  readHex4() {
    const escStart = this.i - 1;
    const hex = this.s.slice(this.i + 1, this.i + 5);
    if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
      this.error(`Invalid \\uXXXX escape`, escStart + 1);
    }
    this.i += 5;
    return parseInt(hex, 16);
  }

  scanObject(depth) {
    if (depth > MAX_DEPTH) throw new PyRecursionError('maximum recursion depth exceeded while decoding a JSON object from a string');
    const result = new Map();
    this.i++; // '{'
    this.skipWhitespace();
    if (this.s[this.i] === '}') { this.i++; return result; }
    for (;;) {
      this.skipWhitespace();
      if (this.s[this.i] !== '"') this.error('Expecting property name enclosed in double quotes');
      const key = this.scanString();
      this.skipWhitespace();
      if (this.s[this.i] !== ':') this.error("Expecting ':' delimiter");
      this.i++;
      this.skipWhitespace();
      // Map.set on an existing key keeps its original position, matching dict.
      result.set(key, this.scanValue(depth));
      this.skipWhitespace();
      const ch = this.s[this.i];
      if (ch === '}') { this.i++; return result; }
      if (ch !== ',') this.error("Expecting ',' delimiter");
      this.i++;
    }
  }

  scanArray(depth) {
    if (depth > MAX_DEPTH) throw new PyRecursionError('maximum recursion depth exceeded while decoding a JSON object from a string');
    const result = [];
    this.i++; // '['
    this.skipWhitespace();
    if (this.s[this.i] === ']') { this.i++; return result; }
    for (;;) {
      this.skipWhitespace();
      result.push(this.scanValue(depth));
      this.skipWhitespace();
      const ch = this.s[this.i];
      if (ch === ']') { this.i++; return result; }
      if (ch !== ',') this.error("Expecting ',' delimiter");
      this.i++;
    }
  }
}

/**
 * json.loads: parse JSON text into the Python value model.
 * @param {string} text
 * @returns {*}
 * @throws {PyJSONDecodeError|PyRecursionError}
 */
export function loads(text) {
  return new Decoder(text).decode();
}

