// Exceptions that mirror the CPython ones this program can die from.
//
// The reference program only catches jsonschema's ValidationError, so anything else
// (a JSON syntax error, an invalid schema, a bad regex, arithmetic on inf) escapes to
// the interpreter: nothing on stdout, a traceback on stderr, exit status 1. These
// classes carry enough information to reproduce that final traceback line.

export class PyError extends Error {
  /** @param {string} pyType dotted name as Python prints it, e.g. "json.decoder.JSONDecodeError" */
  constructor(pyType, message) {
    super(message);
    this.pyType = pyType;
  }
  /** The last line of a Python traceback: "<type>: <message>". */
  get tracebackLine() {
    return `${this.pyType}: ${this.message}`;
  }
}

export class PyJSONDecodeError extends PyError {
  constructor(msg, doc, pos) {
    const lineStart = doc.lastIndexOf('\n', pos - 1) + 1;
    const line = doc.slice(0, pos).split('\n').length;
    const column = pos - lineStart + 1;
    super('json.decoder.JSONDecodeError', `${msg}: line ${line} column ${column} (char ${pos})`);
    this.msg = msg;
    this.doc = doc;
    this.pos = pos;
    this.lineno = line;
    this.colno = column;
  }
}

export class PyRecursionError extends PyError {
  constructor(message) {
    super('RecursionError', message);
  }
}

export class PyReError extends PyError {
  constructor(message) {
    super('re.error', message);
  }
}

