// A faithful-enough port of the argparse behaviour of the reference program's parser:
//
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True, help='instance data (JSON string)')
//   parser.add_argument('--b', type=str, required=True, help='schema (JSON string)')
//
// Only that parser exists, so the usage/help text is fixed and reproduced verbatim.
// The *matching* rules are the general ones, because odd argv shapes are observable:
// `--a=V` works, `--h`/`--he` abbreviate `--help`, `-a` is an unknown option rather
// than an abbreviation of `--a`, `--a -5` passes -5 as a value while `--a -5e3` is
// rejected as an option, and a missing-required error outranks an unrecognized one.

// prog is argparse's os.path.basename(sys.argv[0]); the reference binary reports this.
const PROG = 'test2_executable';

const USAGE = `usage: ${PROG} [-h] --a A --b B\n`;

const HELP = `${USAGE}
options:
  -h, --help  show this help message and exit
  --a A       instance data (JSON string)
  --b B       schema (JSON string)
`;

// argparse's _negative_number_matcher; with no negative-number-like option strings,
// an argv entry matching it is treated as a value, not an option.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const OPTIONS = new Map([
  ['-h', { dest: 'help', takesValue: false }],
  ['--help', { dest: 'help', takesValue: false }],
  ['--a', { dest: 'a', takesValue: true }],
  ['--b', { dest: 'b', takesValue: true }],
]);

/** Thrown for argparse's exits so the caller owns process termination. */
export class ArgumentParserExit extends Error {
  /**
   * @param {number} status exit status (0 for --help, 2 for a usage error)
   * @param {string} stdout text argparse wrote to stdout
   * @param {string} stderr text argparse wrote to stderr
   */
  constructor(status, stdout, stderr) {
    super(stderr || stdout);
    this.status = status;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

function usageError(message) {
  return new ArgumentParserExit(2, '', `${USAGE}${PROG}: error: ${message}\n`);
}

/**
 * Resolve one argv entry to an option, mirroring argparse's _parse_optional.
 * @returns {{option: string, explicitValue: (string|null)}|null} null means "not an option"
 */
function parseOptional(argString) {
  if (argString === '') return null;
  if (argString[0] !== '-') return null;
  if (OPTIONS.has(argString)) return { option: argString, explicitValue: null };
  if (argString.length === 1) return null; // a bare "-" is a positional

  if (argString.includes('=')) {
    const eq = argString.indexOf('=');
    const head = argString.slice(0, eq);
    if (OPTIONS.has(head)) return { option: head, explicitValue: argString.slice(eq + 1) };
  }

  const matches = optionTuples(argString);
  if (matches.length > 1) {
    throw usageError(
      `ambiguous option: ${argString} could match ${matches.map((m) => m.option).join(', ')}`,
    );
  }
  if (matches.length === 1) return matches[0];

  // Looks like a negative number and no option string does, so it is a value.
  if (NEGATIVE_NUMBER.test(argString)) return null;
  if (argString.includes(' ')) return null;

  return { option: argString, explicitValue: null, unknown: true };
}

/** argparse's _get_option_tuples: prefix matching, long options only for "--". */
function optionTuples(argString) {
  const result = [];
  if (argString.startsWith('--')) {
    const eq = argString.indexOf('=');
    const prefix = eq === -1 ? argString : argString.slice(0, eq);
    const explicitValue = eq === -1 ? null : argString.slice(eq + 1);
    for (const option of OPTIONS.keys()) {
      if (option.startsWith(prefix)) result.push({ option, explicitValue });
    }
    return result;
  }
  // Single dash: either an exact short option with a glued value, or a long-option
  // prefix -- and "-a" is neither, since every long option here starts with "--".
  const shortPrefix = argString.slice(0, 2);
  const glued = argString.slice(2);
  for (const option of OPTIONS.keys()) {
    if (option === shortPrefix) result.push({ option, explicitValue: glued });
    else if (option.startsWith(argString)) result.push({ option, explicitValue: null });
  }
  return result;
}

/**
 * parser.parse_args(argv) for the reference parser.
 * @param {string[]} argv arguments after the program name
 * @returns {{a: string, b: string}}
 * @throws {ArgumentParserExit}
 */
export function parseArgs(argv) {
  const values = { a: undefined, b: undefined };
  const extras = [];
  let onlyPositionals = false;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (onlyPositionals) { extras.push(arg); continue; }
    if (arg === '--') { onlyPositionals = true; continue; }

    const parsed = parseOptional(arg);
    if (parsed === null || parsed.unknown) {
      extras.push(arg);
      continue;
    }
    const spec = OPTIONS.get(parsed.option);
    if (!spec.takesValue) {
      if (parsed.explicitValue !== null) {
        throw usageError(`argument ${parsed.option}: ignored explicit argument '${parsed.explicitValue}'`);
      }
      // -h/--help prints to stdout and exits 0 the moment it is reached.
      throw new ArgumentParserExit(0, HELP, '');
    }
    if (parsed.explicitValue !== null) {
      values[spec.dest] = parsed.explicitValue;
      continue;
    }
    // The value is the next argv entry, unless that entry looks like an option.
    const next = argv[i + 1];
    if (next === undefined || parseOptional(next) !== null) {
      throw usageError(`argument ${parsed.option}: expected one argument`);
    }
    values[spec.dest] = next;
    i++;
  }

  // argparse checks required arguments before the caller ever sees leftovers.
  const missing = [];
  if (values.a === undefined) missing.push('--a');
  if (values.b === undefined) missing.push('--b');
  if (missing.length) {
    throw usageError(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length) {
    throw usageError(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return values;
}

