//   ends up in the leftovers; and a missing-required error outranks an unrecognized one.

// argparse's prog is os.path.basename(sys.argv[0]); this is what the reference reports.
const PROG = 'test2_executable';

const USAGE = `usage: ${PROG} [-h] --a A --b B\n`;

const HELP = `${USAGE}
