// number, an argv entry matching this is a value rather than an option.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const HELP_ACTION = { dest: 'help', takesValue: false, name: '-h/--help' };
const A_ACTION = { dest: 'a', takesValue: true, name: '--a' };
const B_ACTION = { dest: 'b', takesValue: true, name: '--b' };

// Insertion order matters: it is the order argparse lists candidates in an
// "ambiguous option" message.
const OPTIONS = new Map([
  ['-h', HELP_ACTION],
  ['--help', HELP_ACTION],
  ['--a', A_ACTION],
  ['--b', B_ACTION],
]);

