function parseOptional(argString) {
  if (argString === '') return null;
  if (argString[0] !== '-') return null;

  const exact = OPTIONS.get(argString);
  if (exact) return { action: exact, optionString: argString, explicitValue: null, sep: null };

  if (argString.length === 1) return null; // a bare "-" is a value

  if (argString.includes('=')) {
    const eq = argString.indexOf('=');
    const head = argString.slice(0, eq);
    const action = OPTIONS.get(head);
    if (action) {
