// The equality relation jsonschema uses for enum, const and uniqueItems.
//
// It is deliberately *not* Python's ==: booleans are first swapped for unique sentinels
// so that `true` never equals `1`, while `1` and `1.0` do compare equal. uniqueItems
// additionally has two code paths -- a sort-based fast path and a brute-force fallback
// used when the elements are not mutually orderable -- and they disagree in corner
// cases (nested booleans), so both are reproduced here.

import { isDict, isList, isStr, isNumeric, numEq, numCmp } from '../python/value.mjs';

// Stand-ins for the two anonymous sentinel objects Python's unbool() substitutes.
const TRUE_SENTINEL = Symbol('True');
const FALSE_SENTINEL = Symbol('False');

/** unbool(): replace booleans with objects that equal nothing but themselves. */
export function unbool(element) {
  if (element === true) return TRUE_SENTINEL;
  if (element === false) return FALSE_SENTINEL;
  return element;
}

const isSentinel = (v) => v === TRUE_SENTINEL || v === FALSE_SENTINEL;

/**
 * jsonschema's _utils.equal.
 * @returns {boolean}
 */
export function equal(one, two) {
  if (one === two) return true; // Python's `one is two` fast path
  // str is a Sequence in Python, so strings are settled before the sequence branch.
  if (isStr(one) || isStr(two)) return one === two;
  if (isList(one) && isList(two)) return sequenceEqual(one, two);
  if (isDict(one) && isDict(two)) return mappingEqual(one, two);
  return sentinelEq(unbool(one), unbool(two));
}

function sequenceEqual(one, two) {
  if (one.length !== two.length) return false;
  return one.every((item, i) => equal(item, two[i]));
}

function mappingEqual(one, two) {
  if (one.size !== two.size) return false;
  for (const [key, value] of one) {
    if (!two.has(key) || !equal(value, two.get(key))) return false;
  }
  return true;
}

/** `==` between two already-unbool'ed scalars. */
function sentinelEq(one, two) {
  if (isSentinel(one) || isSentinel(two)) return one === two;
  if (one === null || two === null) return one === two;
  if (isNumeric(one) && isNumeric(two)) return numEq(one, two);
  return one === two;
}

/** Python's `==`, used by the brute-force uniqueItems path (`e in seen`). */
export function pyEq(one, two) {
  if (one === two) return true;
  if (isSentinel(one) || isSentinel(two)) return one === two;
  if (isList(one) && isList(two)) {
    return one.length === two.length && one.every((item, i) => pyEq(item, two[i]));
  }
  if (isDict(one) && isDict(two)) {
    if (one.size !== two.size) return false;
    for (const [key, value] of one) {
      if (!two.has(key) || !pyEq(value, two.get(key))) return false;
    }
    return true;
  }
  // Python's bool is an int: True == 1 here (unlike equal()), which is exactly why
  // the two uniqueItems paths can disagree.
  const asNum = (v) => (v === true ? 1n : v === false ? 0n : v);
  const a = asNum(one);
  const b = asNum(two);
  if (isNumeric(a) && isNumeric(b)) return numEq(a, b);
  return a === b;
}

/** Signals Python's TypeError from an unorderable comparison inside sorted(). */
class UnorderableError extends Error {}

/** Python's `<`-based three-way comparison; throws where Python raises TypeError. */
function pyCompare(a, b) {
  if (isNumeric(a) && isNumeric(b)) {
    const c = numCmp(a, b);
    if (Number.isNaN(c)) return 0; // nan is unordered but does not raise
    return c;
  }
  if (isStr(a) && isStr(b)) return a < b ? -1 : a > b ? 1 : 0;
  if (isList(a) && isList(b)) {
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) {
      // Python checks == first, then <, so equal prefixes never raise.
      if (pyEq(a[i], b[i])) continue;
      return pyCompare(a[i], b[i]);
    }
    return a.length - b.length === 0 ? 0 : a.length < b.length ? -1 : 1;
  }
  // dicts, None and the bool sentinels have no ordering at all.
  throw new UnorderableError('not supported between instances');
}

/** sorted(): binary-insertion sort, which is what CPython's Timsort uses at this size. */
function pySorted(items) {
  const out = [];
  for (const item of items) {
    let lo = 0;
    let hi = out.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (pyCompare(item, out[mid]) < 0) hi = mid;
      else lo = mid + 1;
    }
    out.splice(lo, 0, item);
  }
  return out;
}

/**
 * jsonschema's _utils.uniq: true when every element is unique.
 * @param {Array} container
 * @returns {boolean}
 */
export function uniq(container) {
  try {
    const sorted = pySorted(container.map(unbool));
    for (let i = 1; i < sorted.length; i++) {
      if (equal(sorted[i - 1], sorted[i])) return false;
    }
  } catch (err) {
    if (!(err instanceof UnorderableError)) throw err;
    // Fallback: O(n^2) membership testing with Python's ==.
    const seen = [];
    for (const element of container) {
      const e = unbool(element);
      if (seen.some((s) => pyEq(s, e))) return false;
      seen.push(e);
    }
  }
  return true;
}

