  if (isNumeric(a) && isNumeric(b)) {
    const c = numCmp(a, b);
    if (Number.isNaN(c)) return 0; // nan is unordered but does not raise
    return c;
  }
  if (isStr(a) && isStr(b)) return a < b ? -1 : a > b ? 1 : 0;
  if (isList(a) && isList(b)) {
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) {
      // Python checks == first, then <, so equal prefixes never raise.
      if (pyEq(a[i], b[i])) continue;
      return pyCompare(a[i], b[i]);
    }
    return a.length - b.length === 0 ? 0 : a.length < b.length ? -1 : 1;
  }
  // dicts, None and the bool sentinels have no ordering at all.
  throw new UnorderableError('not supported between instances');
}

/** sorted(): binary-insertion sort, which is what CPython's Timsort uses at this size. */
function pySorted(items) {
  const out = [];
  for (const item of items) {
    let lo = 0;
    let hi = out.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (pyCompare(item, out[mid]) < 0) hi = mid;
      else lo = mid + 1;
    }
    out.splice(lo, 0, item);
  }
  return out;
}

/**
 * jsonschema's _utils.uniq: true when every element is unique.
 * @param {Array} container
 * @returns {boolean}
 */
export function uniq(container) {
  try {
    const sorted = pySorted(container.map(unbool));
    for (let i = 1; i < sorted.length; i++) {
      if (equal(sorted[i - 1], sorted[i])) return false;
    }
  } catch (err) {
    if (!(err instanceof UnorderableError)) throw err;
    // Fallback: O(n^2) membership testing with Python's ==.
    const seen = [];
    for (const element of container) {
      const e = unbool(element);
      if (seen.some((s) => pyEq(s, e))) return false;
      seen.push(e);
    }
  }
  return true;
}

