// jsonschema's TypeChecker: the mapping from JSON Schema type names to predicates.
//
// The draft 6+ twist is that a float with no fractional part counts as an "integer",
// so 1.0 satisfies {"type": "integer"}. Booleans are excluded from number/integer even
// though Python's bool is a subclass of int.

import { isBool, isDict, isFloat, isInt, isList, isNone, isNumeric, isStr } from '../python/value.mjs';

const isIntegerStrict = (v) => isInt(v);
const isIntegerOrIntegralFloat = (v) => isInt(v) || (isFloat(v) && Number.isInteger(v));

/** Draft 3/4 type checker. */
export const DRAFT4_TYPES = new Map([
  ['array', isList],
  ['boolean', isBool],
  ['integer', isIntegerStrict],
  ['object', isDict],
  ['null', isNone],
  ['number', isNumeric],
  ['string', isStr],
]);

/** Draft 6 and later: "integer" also accepts integral floats. */
export const DRAFT6_TYPES = new Map(DRAFT4_TYPES).set('integer', isIntegerOrIntegralFloat);

export class TypeChecker {
  /** @param {Map<string, (v: *) => boolean>} checkers */
  constructor(checkers) {
    this.checkers = checkers;
  }

  /**
   * @param {*} instance
   * @param {string} type a JSON Schema type name
   * @returns {boolean}
   * @throws {UndefinedTypeCheck} when the schema names a type the dialect has no checker for
   */
  isType(instance, type) {
    const checker = this.checkers.get(type);
    if (checker === undefined) throw new UndefinedTypeCheck(type);
    return checker(instance);
  }
}

export class UndefinedTypeCheck extends Error {
  constructor(type) {
    super(`Type ${JSON.stringify(type)} is unknown to this type checker`);
    this.type = type;
  }
}

export const draft4TypeChecker = new TypeChecker(DRAFT4_TYPES);
export const draft6TypeChecker = new TypeChecker(DRAFT6_TYPES);

