  return ch;
}

// Escapes Python accepts after a backslash as themselves (punctuation and a few letters).
const SIMPLE_ESCAPES = new Map([
  ['a', '\\x07'], ['b', null], ['f', '\\f'], ['n', '\\n'], ['r', '\\r'],
  ['t', '\\t'], ['v', '\\v'], ['0', '\\x00'],
]);

class Translator {
  constructor(pattern) {
    this.src = pattern;
    this.i = 0;
    this.flags = new Set(['u']);
    this.verbose = false;
    this.ascii = false;
    this.out = '';
    this.groupCount = 0;
  }

  error(msg) {
    throw new PyReError(`${msg} at position ${this.i}`);
  }

  get digits() { return this.ascii ? ASCII_DIGIT : UNICODE_DIGIT; }
  get word() { return this.ascii ? ASCII_WORD : UNICODE_WORD; }
  get space() { return this.ascii ? ASCII_SPACE : UNICODE_SPACE; }

  translate() {
    this.readGlobalFlags();
    this.out = this.parse(0);
    if (this.i < this.src.length) this.error('unbalanced parenthesis');
    return { source: this.out, flags: [...this.flags].join('') };
  }

  /** Python requires global inline flags such as (?i) at the very start of the pattern. */
  readGlobalFlags() {
    const FLAG_MAP = { i: 'i', m: 'm', s: 's' };
    for (;;) {
      const m = /^\(\?([aiLmsux]+)\)/.exec(this.src.slice(this.i));
      if (!m) return;
      for (const flag of m[1]) {
        if (flag === 'x') this.verbose = true;
        else if (flag === 'a') this.ascii = true;
        else if (flag === 'u') continue;
        else if (flag === 'L') this.error('cannot use LOCALE flag with a str pattern');
        else this.flags.add(FLAG_MAP[flag]);
      }
      this.i += m[0].length;
    }
  }

  /** Parse an alternation up to a closing ')' (depth > 0) or end of input. */
  parse(depth) {
    const branches = [''];
    for (;;) {
      const ch = this.src[this.i];
      if (ch === undefined) {
        if (depth > 0) this.error('missing ), unterminated subpattern');
        break;
      }
      if (ch === ')') {
        if (depth === 0) this.error('unbalanced parenthesis');
        break;
      }
      if (ch === '|') {
        this.i++;
        branches.push('');
        continue;
      }
      branches[branches.length - 1] += this.parseAtomWithQuantifier(depth);
    }
    return branches.join('|');
  }

  parseAtomWithQuantifier(depth) {
    const atom = this.parseAtom(depth);
    if (atom === '') return '';
    return atom + this.parseQuantifier();
  }

  parseQuantifier() {
    const ch = this.src[this.i];
    let quant = '';
    if (ch === '*' || ch === '+' || ch === '?') {
      quant = ch;
      this.i++;
    } else if (ch === '{') {
      const m = /^\{(\d*)(,(\d*))?\}/.exec(this.src.slice(this.i));
      // A brace that is not a well-formed repeat is a literal in Python; handled by
      // parseAtom, so we only get here for the real thing.
      if (!m || (m[1] === '' && m[2] === undefined)) return '';
      // Python reads {,n} as {0,n}; JavaScript would take it literally.
      const low = m[1] === '' ? '0' : m[1];
      quant = m[2] === undefined ? `{${low}}` : `{${low},${m[3]}}`;
      this.i += m[0].length;
    } else {
      return '';
    }
    // Lazy or possessive suffix. JavaScript has no possessive quantifiers.
    if (this.src[this.i] === '?') { quant += '?'; this.i++; }
    else if (this.src[this.i] === '+') this.error('possessive quantifiers are not supported');
    return quant;
  }

  parseAtom(depth) {
    const ch = this.src[this.i];
    if (this.verbose) {
      if (/\s/.test(ch)) { this.i++; return ''; }
      if (ch === '#') {
        while (this.i < this.src.length && this.src[this.i] !== '\n') this.i++;
        return '';
      }
    }
    switch (ch) {
      case '(': return this.parseGroup(depth);
      case '[': return this.parseClass();
      case '\\': return this.parseEscape();
      case '.': this.i++; return '.';
      case '^': this.i++; return '^';
      case '$':
        this.i++;
        // Python's $ also matches before a final newline. With the 'm' flag JavaScript's
        // $ already matches before every newline, which is Python's multiline meaning.
        return this.flags.has('m') ? '$' : '(?=\\n?$)';
      case '*': case '+': case '?':
        this.error('nothing to repeat');
        break;
      default:
        this.i++;
        return escapeLiteral(ch);
    }
  }

  parseGroup(depth) {
    const src = this.src;
    this.i++; // '('
    if (src[this.i] !== '?') {
      this.groupCount++;
      const body = this.parse(depth + 1);
      this.expect(')');
      return `(${body})`;
    }
    this.i++; // '?'
    const ch = src[this.i];

    if (ch === '#') { // (?#comment)
      const end = src.indexOf(')', this.i);
      if (end === -1) this.error('missing ), unterminated comment');
      this.i = end + 1;
      return '';
    }
    if (ch === 'P') {
      this.i++;
      if (src[this.i] === '<') { // (?P<name>...)
        const end = src.indexOf('>', this.i);
        if (end === -1) this.error('missing >, unterminated name');
        const name = src.slice(this.i + 1, end);
        this.i = end + 1;
        this.groupCount++;
        const body = this.parse(depth + 1);
        this.expect(')');
        return `(?<${name}>${body})`;
      }
      if (src[this.i] === '=') { // (?P=name)
        const end = src.indexOf(')', this.i);
        if (end === -1) this.error('missing ), unterminated name');
        const name = src.slice(this.i + 1, end);
        this.i = end + 1;
        return `\\k<${name}>`;
      }
      this.error('unknown extension ?P');
    }
    if (ch === ':' || ch === '=' || ch === '!') {
      this.i++;
      const body = this.parse(depth + 1);
      this.expect(')');
      return `(?${ch}${body})`;
    }
    if (ch === '<') { // lookbehind (?<= / (?<!  -- or a bare (?<name> which Python rejects
      const kind = src[this.i + 1];
      if (kind !== '=' && kind !== '!') this.error('unknown extension ?<');
      this.i += 2;
      const body = this.parse(depth + 1);
      this.expect(')');
      return `(?<${kind}${body})`;
    }
    if (ch === '>') this.error('atomic groups are not supported');
    if (ch === '(') this.error('conditional patterns are not supported');
    if (/[aiLmsux]/.test(ch)) {
      // Scoped flags (?i:...) or a mid-pattern global flag, which Python 3.11+ rejects.
      const m = /^([aiLmsux]+)([:)])/.exec(src.slice(this.i));
      if (!m) this.error('missing -, : or )');
      this.error('global flags not at the start of the expression');
    }
    this.error('unknown extension');
  }

  expect(ch) {
    if (this.src[this.i] !== ch) this.error(`missing ${ch}`);
    this.i++;
  }

  /**
   * Character class. Members are collected as either plain class bodies or, when a
   * complement escape such as \W appears, as alternatives -- because 'u'-mode RegExp
   * character classes cannot express a union with a complement.
   */
  parseClass() {
    this.i++; // '['
    const negated = this.src[this.i] === '^';
    if (negated) this.i++;
    if (this.src[this.i] === ']') this.error('unterminated character set'); // Python agrees
    let body = '';
    const alternatives = [];
    for (;;) {
      const ch = this.src[this.i];
      if (ch === undefined) this.error('unterminated character set');
      if (ch === ']') { this.i++; break; }
      if (ch === '\\') {
        const piece = this.parseClassEscape();
        if (piece.alternative) alternatives.push(piece.alternative);
        else body += piece.body;
        continue;
      }
      // A range like a-z, unless the '-' is the last character in the class.
      const next = this.src[this.i + 1];
      if (next === '-' && this.src[this.i + 2] !== ']' && this.src[this.i + 2] !== undefined) {
        const hi = this.src[this.i + 2];
        if (hi === '\\') {
          // Python only allows literal escapes as a range bound.
          const save = this.i;
          this.i += 2;
          const piece = this.parseClassEscape();
          if (piece.alternative || !piece.single) { this.i = save; this.error('bad character range'); }
          body += `${escapeClassLiteral(ch)}-${piece.body}`;
          continue;
        }
        body += `${escapeClassLiteral(ch)}-${escapeClassLiteral(hi)}`;
        this.i += 3;
        continue;
      }
      body += escapeClassLiteral(ch);
      this.i++;
    }
    if (!alternatives.length) {
      return `[${negated ? '^' : ''}${body}]`;
    }
    // Rewrite as a single-code-point alternation so complements can participate.
    const parts = [...alternatives];
    if (body) parts.unshift(`[${body}]`);
    const union = parts.join('|');
    return negated ? `(?:(?!${union})[\\s\\S])` : `(?:${union})`;
  }

  /** One backslash escape inside a character class. */
  parseClassEscape() {
    this.i++; // '\'
    const ch = this.src[this.i];
    if (ch === undefined) this.error('bad escape (end of pattern)');
    this.i++;
    switch (ch) {
      case 'd': return { body: this.digits };
      case 'D': return this.ascii ? { alternative: `[^${ASCII_DIGIT}]` } : { body: '\\P{Nd}' };
      case 'w': return { body: this.word };
      case 'W': return { alternative: `[^${this.word}]` };
      case 's': return { body: this.space };
      case 'S': return { alternative: `[^${this.space}]` };
      case 'b': return { body: '\\x08', single: true }; // \b is a backspace inside a class
      case 'x': return { body: this.readHexEscape(2), single: true };
      case 'u': return { body: this.readHexEscape(4), single: true };
      case 'U': return { body: this.readHexEscape(8), single: true };
      case 'N': return { body: this.readNamedEscape(), single: true };
      default: {
        const simple = SIMPLE_ESCAPES.get(ch);
        if (simple) return { body: simple, single: true };
        if (/[0-7]/.test(ch)) return { body: this.readOctalEscape(ch), single: true };
        if (/[0-9]/.test(ch)) this.error(`bad escape \\${ch}`);
        if (/[A-Za-z]/.test(ch)) this.error(`bad escape \\${ch}`);
        return { body: escapeClassLiteral(ch), single: true };
      }
    }
  }

  /** One backslash escape outside a character class. */
  parseEscape() {
    this.i++; // '\'
    const ch = this.src[this.i];
    if (ch === undefined) this.error('bad escape (end of pattern)');
    this.i++;
    switch (ch) {
      case 'd': return `[${this.digits}]`;
      case 'D': return `[^${this.digits}]`;
      case 'w': return `[${this.word}]`;
      case 'W': return `[^${this.word}]`;
      case 's': return `[${this.space}]`;
      case 'S': return `[^${this.space}]`;
      case 'b': return this.wordBoundary(true);
      case 'B': return this.wordBoundary(false);
      case 'A': return '^'; // no 'm' flag unless requested, so ^ is the string start
      case 'Z': return '$'; // Python's \Z is a strict end of string
      case 'x': return this.readHexEscape(2);
      case 'u': return this.readHexEscape(4);
      case 'U': return this.readHexEscape(8);
      case 'N': return this.readNamedEscape();
      default: {
        if (ch === '0') return '\\x00';
        if (/[1-9]/.test(ch)) {
          // A group reference; Python would read it as octal only with a leading 0.
          let digits = ch;
          while (/[0-9]/.test(this.src[this.i] ?? '') && digits.length < 2) {
            digits += this.src[this.i];
            this.i++;
          }
          return `\\${digits}`;
        }
        const simple = SIMPLE_ESCAPES.get(ch);
        if (simple) return simple;
        if (/[A-Za-z]/.test(ch)) this.error(`bad escape \\${ch}`);
        return escapeLiteral(ch);
      }
    }
  }

  wordBoundary(inside) {
    const w = `[${this.word}]`;
    return inside
      ? `(?:(?<=${w})(?!${w})|(?<!${w})(?=${w}))`
      : `(?:(?<=${w})(?=${w})|(?<!${w})(?!${w}))`;
  }

  readHexEscape(width) {
    const hex = this.src.slice(this.i, this.i + width);
    if (hex.length !== width || !/^[0-9a-fA-F]+$/.test(hex)) this.error('incomplete escape');
    this.i += width;
    const cp = parseInt(hex, 16);
    if (cp > 0x10ffff) this.error('invalid escape');
    return `\\u{${cp.toString(16)}}`;
  }

  readOctalEscape(first) {
    let digits = first;
    while (digits.length < 3 && /[0-7]/.test(this.src[this.i] ?? '')) {
      digits += this.src[this.i];
      this.i++;
    }
    return `\\u{${parseInt(digits, 8).toString(16)}}`;
  }

  /** \N{LATIN SMALL LETTER A}: needs a Unicode name table Python has and we do not. */
  readNamedEscape() {
    this.error('missing {');
  }
}

const cache = new Map();

/**
 * Compile a Python pattern to a RegExp, as `re.compile` would.
 * @param {string} pattern
 * @returns {RegExp}
 * @throws {PyReError} where Python's re.error would escape to the interpreter
 */
export function compilePattern(pattern) {
  const cached = cache.get(pattern);
  if (cached) {
    if (cached instanceof PyReError) throw cached;
    return cached;
  }
  let result;
  try {
    const { source, flags } = new Translator(pattern).translate();
    result = new RegExp(source, flags);
  } catch (err) {
    result = err instanceof PyReError ? err : new PyReError(String(err.message));
    cache.set(pattern, result);
    throw result;
  }
  cache.set(pattern, result);
  return result;
}

/**
 * re.search(pattern, string) as a boolean.
 * @param {string} pattern
 * @param {string} text
 * @returns {boolean}
 */
export function reSearch(pattern, text) {
  const re = compilePattern(pattern);
  re.lastIndex = 0;
  return re.test(text);
}

