// Translate a Python `re` pattern into an equivalent JavaScript RegExp.
//
// jsonschema applies patterns with re.search(), i.e. unanchored. The engines agree on
// the common syntax but differ in ways that show up in real schemas:
//
//   * \d \w \s \b are Unicode-aware in Python 3 but ASCII in JavaScript.
//   * Python's `$` also matches just before a trailing newline; JavaScript's does not.
//   * Python spells named groups (?P<n>...) / (?P=n), and has (?#comments), scoped
//     flags (?i:...), atomic groups (?>...) and possessive quantifiers a*+.
//   * `]` directly after `[` is a literal member in Python; `{2}` with nothing to
//     repeat is an error, while a bare `{`, `}` or `]` elsewhere is a literal -- and
//     'u'-mode RegExp rejects all of those.
//   * \1 may be an octal escape or a group reference depending on the digits.
//
// The 'u' flag is required (it is what makes \p{...} available), which is also why
// every literal has to be escaped carefully.

import { PyReError } from './exceptions.mjs';

// Unicode expansions of Python's class escapes, as character-class *bodies*.
const UNICODE_DIGIT = '\\p{Nd}';
const UNICODE_WORD = '\\p{L}\\p{N}_';
// Python's str.isspace(): \t\n\v\f\r, \x1c-\x1f, \x20, \x85 and the Z* categories.
const UNICODE_SPACE = '\\t\\n\\v\\f\\r\\x1c-\\x1f\\x20\\x85\\p{Zs}\\u2028\\u2029';

const ASCII_DIGIT = '0-9';
const ASCII_WORD = 'A-Za-z0-9_';
const ASCII_SPACE = ' \\t\\n\\r\\f\\v';

/** Characters that must be backslash-escaped to appear literally outside a class. */
const LITERAL_ESCAPE = new Set([...'^$\\.*+?()[]{}|/']);
/** ... and inside one. */
const CLASS_LITERAL_ESCAPE = new Set([...'^\\]-[/']);

/** Keep the emitted pattern 7-bit clean so it is safe to read and to log. */
function safeChar(ch) {
  const cp = ch.codePointAt(0);
  if (cp < 0x20 || cp === 0x7f) return '\\x' + cp.toString(16).padStart(2, '0');
  return ch;
}

const escapeLiteral = (ch) => (LITERAL_ESCAPE.has(ch) ? '\\' + ch : safeChar(ch));
const escapeClassLiteral = (ch) => (CLASS_LITERAL_ESCAPE.has(ch) ? '\\' + ch : safeChar(ch));

// Escapes Python accepts after a backslash, mapped to their JS spelling.
const SIMPLE_ESCAPES = new Map([
  ['a', '\\x07'], ['f', '\\f'], ['n', '\\n'], ['r', '\\r'], ['t', '\\t'], ['v', '\\v'],
]);

const OCTAL = /[0-7]/;
const DIGIT = /[0-9]/;

/** The case variants a character matches under Python's case-insensitive matching. */
function caseVariants(ch) {
  const set = new Set([ch, ch.toLowerCase(), ch.toUpperCase()]);
  return [...set].filter((c) => [...c].length === 1);
}

class Translator {
  constructor(pattern) {
    this.src = pattern;
    this.i = 0;
    this.jsFlags = new Set(['u']);
    // Global (pattern-wide) modes, set by a leading (?imsxa).
    this.verbose = false;
    this.ascii = false;
    // Scope-local modes, toggled by (?i:...) and friends. Global i/m/s are handled by
    // JS flags instead, so these only ever describe a scoped override.
    this.scope = { i: false, m: false, s: false };
    this.groupNumber = 0;
    this.groupNames = new Map(); // group number -> emitted JS name
    this.helpers = 0;
    this.maxBackref = 0;
  }

  error(msg) {
    throw new PyReError(`${msg} at position ${this.i}`);
  }

  get digits() { return this.ascii ? ASCII_DIGIT : UNICODE_DIGIT; }
  get word() { return this.ascii ? ASCII_WORD : UNICODE_WORD; }
  get space() { return this.ascii ? ASCII_SPACE : UNICODE_SPACE; }
  get caseless() { return this.scope.i || this.jsFlags.has('i'); }
  get multiline() { return this.scope.m || this.jsFlags.has('m'); }
  get dotAll() { return this.scope.s || this.jsFlags.has('s'); }

  translate() {
    this.readGlobalFlags();
    let source = this.parse(0);
    if (this.i < this.src.length) this.error('unbalanced parenthesis');
    if (this.maxBackref > this.groupNumber) {
      throw new PyReError(`invalid group reference ${this.maxBackref} at position 0`);
    }
    // Numeric backreferences were emitted against generated names; point the ones that
    // belong to (?P<name>...) groups at the real name.
    source = source.replace(/\\k<_g(\d+)>/g, (_, n) => {
      const name = this.groupNames.get(Number(n));
      return `\\k<${name ?? '_g' + n}>`;
    });
    return { source, flags: [...this.jsFlags].join('') };
  }

  /** Python requires pattern-wide inline flags such as (?i) at the very start. */
  readGlobalFlags() {
    const JS_FLAG = { i: 'i', m: 'm', s: 's' };
    for (;;) {
      const m = /^\(\?([aiLmsux]+)\)/.exec(this.src.slice(this.i));
      if (!m) return;
      for (const flag of m[1]) {
        if (flag === 'x') this.verbose = true;
        else if (flag === 'a') this.ascii = true;
        else if (flag === 'u') continue;
        else if (flag === 'L') this.error('cannot use LOCALE flag with a str pattern');
        else this.jsFlags.add(JS_FLAG[flag]);
      }
      this.i += m[0].length;
    }
  }

  /** Parse an alternation up to a closing ')' (depth > 0) or end of input. */
  parse(depth) {
    const branches = [''];
    for (;;) {
      const ch = this.src[this.i];
      if (ch === undefined) {
        if (depth > 0) this.error('missing ), unterminated subpattern');
        break;
      }
      if (ch === ')') {
        if (depth === 0) this.error('unbalanced parenthesis');
        break;
      }
      if (ch === '|') {
        this.i++;
        branches.push('');
        continue;
      }
      branches[branches.length - 1] += this.parseAtomWithQuantifier(depth);
    }
    return branches.join('|');
  }

  parseAtomWithQuantifier(depth) {
    const start = this.i;
    const atom = this.parseAtom(depth);
    if (atom === '') return ''; // a comment or skipped verbose whitespace
    const quant = this.parseQuantifier(atom, start);
    if (quant !== '' && this.peekQuantifier()) this.error('multiple repeat');
    return quant === '' ? atom : quant;
  }

  /** True when the next characters would start another quantifier. */
  peekQuantifier() {
    const ch = this.src[this.i];
    if (ch === '*' || ch === '+' || ch === '?') return true;
    return ch === '{' && this.repeatSpec() !== null;
  }

  /** Match a well-formed {m}, {m,}, {,n} or {m,n} at the cursor. */
  repeatSpec() {
    const m = /^\{(\d*)(?:(,)(\d*))?\}/.exec(this.src.slice(this.i));
    if (!m) return null;
    if (m[1] === '' && m[2] === undefined) return null; // "{}" is literal
    if (m[1] === '' && m[3] === '') return null; // "{,}" is literal
    return m;
  }

  /**
   * Apply any quantifier following `atom`.
   * @returns {string} the quantified atom, or '' when there is no quantifier
   */
  parseQuantifier(atom, atomStart) {
    const ch = this.src[this.i];
    let quant;
    if (ch === '*' || ch === '+' || ch === '?') {
      quant = ch;
      this.i++;
    } else if (ch === '{') {
      const spec = this.repeatSpec();
      if (spec === null) return '';
      const low = spec[1] === '' ? '0' : spec[1];
      quant = spec[2] === undefined ? `{${low}}` : `{${low},${spec[3]}}`;
      this.i += spec[0].length;
    } else {
      return '';
    }
    if (this.src[this.i] === '?') { // lazy
      this.i++;
      return atom + quant + '?';
    }
    if (this.src[this.i] === '+') { // possessive: emulate with an atomic group
      this.i++;
      return this.atomic(atom + quant);
    }
    return atom + quant;
  }

  /** Atomic grouping via the lookahead-plus-backreference idiom. */
  atomic(body) {
    const name = `_a${++this.helpers}`;
    return `(?:(?=(?<${name}>${body}))\\k<${name}>)`;
  }

  parseAtom(depth) {
    const ch = this.src[this.i];
    if (this.verbose) {
      if (/\s/.test(ch)) { this.i++; return ''; }
      if (ch === '#') {
        while (this.i < this.src.length && this.src[this.i] !== '\n') this.i++;
        return '';
      }
    }
    switch (ch) {
      case '(': return this.parseGroup(depth);
      case '[': return this.parseClass();
      case '\\': return this.parseEscape();
      case '.':
        this.i++;
        return this.dotAll ? '[\\s\\S]' : '.';
      case '^':
        this.i++;
        // Python's multiline ^ matches after any newline; without it, only at the start.
        if (!this.multiline) return '^';
        return this.jsFlags.has('m') ? '^' : '(?:^|(?<=\\n))';
      case '$':
        this.i++;
        // Python's plain $ also matches before a single trailing newline.
        if (!this.multiline) return '(?=\\n?$)';
        return this.jsFlags.has('m') ? '$' : '(?=\\n|$)';
      case '*': case '+': case '?':
        this.error('nothing to repeat');
        break; // unreachable
      case '{':
        // A well-formed repeat with no preceding atom is an error, not a literal.
        if (this.repeatSpec() !== null) this.error('nothing to repeat');
        this.i++;
        return '\\{';
      default:
        this.i++;
        return this.literal(ch);
    }
  }

  /** Emit a literal character, expanding case variants when caselessness is scoped. */
  literal(ch) {
    if (this.scope.i && !this.jsFlags.has('i')) {
      const variants = caseVariants(ch);
      if (variants.length > 1) return `[${variants.map(escapeClassLiteral).join('')}]`;
    }
    return escapeLiteral(ch);
  }

  parseGroup(depth) {
    const src = this.src;
    this.i++; // '('
    if (src[this.i] !== '?') {
      const number = ++this.groupNumber;
      const body = this.parse(depth + 1);
      this.expect(')');
      return `(?<_g${number}>${body})`;
    }
    this.i++; // '?'
    const ch = src[this.i];

    if (ch === '#') { // (?#comment)
      const end = src.indexOf(')', this.i);
      if (end === -1) this.error('missing ), unterminated comment');
      this.i = end + 1;
      return '';
    }
    if (ch === 'P') {
      this.i++;
      if (src[this.i] === '<') { // (?P<name>...)
        const end = src.indexOf('>', this.i);
        if (end === -1) this.error('missing >, unterminated name');
        const name = src.slice(this.i + 1, end);
        if (!/^[A-Za-z_]\w*$/.test(name)) this.error(`bad character in group name '${name}'`);
        this.i = end + 1;
        const number = ++this.groupNumber;
        this.groupNames.set(number, name);
        const body = this.parse(depth + 1);
        this.expect(')');
        return `(?<${name}>${body})`;
      }
      if (src[this.i] === '=') { // (?P=name)
        const end = src.indexOf(')', this.i);
        if (end === -1) this.error('missing ), unterminated name');
        const name = src.slice(this.i + 1, end);
        this.i = end + 1;
        return `\\k<${name}>`;
      }
      this.error('unknown extension ?P');
    }
    if (ch === ':' || ch === '=' || ch === '!') {
      this.i++;
      const body = this.parse(depth + 1);
      this.expect(')');
      return `(?${ch}${body})`;
    }
    if (ch === '<') { // lookbehind (?<= and (?<!
      const kind = src[this.i + 1];
      if (kind !== '=' && kind !== '!') this.error('unknown extension ?<');
      this.i += 2;
      const body = this.parse(depth + 1);
      this.expect(')');
      return `(?<${kind}${body})`;
    }
    if (ch === '>') { // atomic group
      this.i++;
      const body = this.parse(depth + 1);
      this.expect(')');
      return this.atomic(body);
    }
    if (ch === '(') this.error('conditional patterns are not supported');
    return this.parseScopedFlags(depth);
  }

  /** (?imsxa-imsx:...) -- scoped flags, which JavaScript cannot express directly. */
  parseScopedFlags(depth) {
    const m = /^([aiLmsux]*)(?:-([imsx]+))?([:)])/.exec(this.src.slice(this.i));
    if (!m) this.error('missing -, : or )');
    if (m[3] === ')') this.error('global flags not at the start of the expression');
    this.i += m[0].length;
    const saved = { ...this.scope };
    const savedVerbose = this.verbose;
    for (const flag of m[1] ?? '') {
      if (flag === 'x') this.verbose = true;
      else if (flag === 'a') this.ascii = true;
      else if (flag === 'u' || flag === 'L') continue;
      else this.scope[flag] = true;
    }
    for (const flag of m[2] ?? '') {
      if (flag === 'x') this.verbose = false;
      else this.scope[flag] = false;
    }
    const body = this.parse(depth + 1);
    this.expect(')');
    this.scope = saved;
    this.verbose = savedVerbose;
    return `(?:${body})`;
  }

  expect(ch) {
    if (this.src[this.i] !== ch) this.error(`missing ${ch}`);
    this.i++;
  }

  /**
   * Character class. Members become either plain class bodies or, when a complement
   * escape such as \W appears, alternatives -- 'u'-mode classes cannot union with a
   * complement, but an alternation of single-code-point branches can.
   */
  parseClass() {
    this.i++; // '['
    const negated = this.src[this.i] === '^';
    if (negated) this.i++;
    let body = '';
    const alternatives = [];
    if (this.src[this.i] === ']') { // a leading ']' is a literal member in Python
      body += '\\]';
      this.i++;
    }
    for (;;) {
      const ch = this.src[this.i];
      if (ch === undefined) this.error('unterminated character set');
      if (ch === ']') { this.i++; break; }
      if (ch === '\\') {
        const piece = this.parseClassEscape();
        if (piece.alternative) alternatives.push(piece.alternative);
        else body += piece.body;
        continue;
      }
      // A range like a-z, unless the '-' is the class's last character.
      const dash = this.src[this.i + 1];
      const hi = this.src[this.i + 2];
      if (dash === '-' && hi !== ']' && hi !== undefined) {
        if (hi === '\\') {
          const save = this.i;
          this.i += 2;
          const piece = this.parseClassEscape();
          if (piece.alternative || !piece.single) { this.i = save; this.error('bad character range'); }
          body += `${escapeClassLiteral(ch)}-${piece.body}`;
          continue;
        }
        if (hi.codePointAt(0) < ch.codePointAt(0)) {
          this.error(`bad character range ${ch}-${hi}`);
        }
        body += this.classRange(ch, hi);
        this.i += 3;
        continue;
      }
      body += this.classLiteral(ch);
      this.i++;
    }
    if (!alternatives.length) {
      if (body === '') return negated ? '[\\s\\S]' : '[^\\s\\S]';
      return `[${negated ? '^' : ''}${body}]`;
    }
    // Rewrite as a single-code-point alternation so complements can participate.
    const parts = [...alternatives];
    if (body) parts.unshift(`[${body}]`);
    const union = parts.join('|');
    return negated ? `(?:(?!${union})[\\s\\S])` : `(?:${union})`;
  }

  classLiteral(ch) {
    if (this.scope.i && !this.jsFlags.has('i')) {
      return caseVariants(ch).map(escapeClassLiteral).join('');
    }
    return escapeClassLiteral(ch);
  }

  classRange(lo, hi) {
    const plain = `${escapeClassLiteral(lo)}-${escapeClassLiteral(hi)}`;
    if (!this.scope.i || this.jsFlags.has('i')) return plain;
    // Enumerate small ranges so scoped caselessness covers them too.
    const from = lo.codePointAt(0);
    const to = hi.codePointAt(0);
    if (to - from > 256) return plain;
    let extra = '';
    for (let cp = from; cp <= to; cp++) {
      for (const variant of caseVariants(String.fromCodePoint(cp))) {
        if (variant.codePointAt(0) < from || variant.codePointAt(0) > to) {
          extra += escapeClassLiteral(variant);
        }
      }
    }
    return plain + extra;
  }

  /** One backslash escape inside a character class. */
  parseClassEscape() {
    this.i++; // '\'
    const ch = this.src[this.i];
    if (ch === undefined) this.error('bad escape (end of pattern)');
    this.i++;
    switch (ch) {
      case 'd': return { body: this.digits };
      case 'D': return this.ascii ? { alternative: `[^${ASCII_DIGIT}]` } : { body: '\\P{Nd}' };
      case 'w': return { body: this.word };
      case 'W': return { alternative: `[^${this.word}]` };
      case 's': return { body: this.space };
      case 'S': return { alternative: `[^${this.space}]` };
      case 'b': return { body: '\\x08', single: true }; // backspace inside a class
      case 'x': return { body: this.readHexEscape(2), single: true };
      case 'u': return { body: this.readHexEscape(4), single: true };
      case 'U': return { body: this.readHexEscape(8), single: true };
      case 'N': return { body: this.readNamedEscape(), single: true };
      default: {
        const simple = SIMPLE_ESCAPES.get(ch);
        if (simple) return { body: simple, single: true };
        if (OCTAL.test(ch)) return { body: this.readOctalEscape(ch), single: true };
        if (DIGIT.test(ch)) this.error(`bad escape \\${ch}`);
        if (/[A-Za-z]/.test(ch)) this.error(`bad escape \\${ch}`);
        return { body: escapeClassLiteral(ch), single: true };
      }
    }
  }

  /** One backslash escape outside a character class. */
  parseEscape() {
    this.i++; // '\'
    const ch = this.src[this.i];
    if (ch === undefined) this.error('bad escape (end of pattern)');
    this.i++;
    switch (ch) {
      case 'd': return `[${this.digits}]`;
      case 'D': return `[^${this.digits}]`;
      case 'w': return `[${this.word}]`;
      case 'W': return `[^${this.word}]`;
      case 's': return `[${this.space}]`;
      case 'S': return `[^${this.space}]`;
      case 'b': return this.wordBoundary(true);
      case 'B': return this.wordBoundary(false);
      case 'A': return '^'; // start of string; ^ means that unless 'm' is set
      case 'Z': return '$'; // Python's \Z is a strict end of string
      case 'x': return this.readHexEscape(2);
      case 'u': return this.readHexEscape(4);
      case 'U': return this.readHexEscape(8);
      case 'N': return this.readNamedEscape();
      default: {
        if (ch === '0') return this.readOctalEscape('0');
        if (DIGIT.test(ch)) return this.digitEscape(ch);
        const simple = SIMPLE_ESCAPES.get(ch);
        if (simple) return simple;
        if (/[A-Za-z]/.test(ch)) this.error(`bad escape \\${ch}`);
        return escapeLiteral(ch);
      }
    }
  }

  /**
   * `\1` and friends: three octal digits make a character, anything else is a group
   * reference. (Python's own comment on this code reads "sigh".)
   */
  digitEscape(first) {
    const next = this.src[this.i];
    if (next !== undefined && DIGIT.test(next)) {
      const second = next;
      const third = this.src[this.i + 1];
      if (OCTAL.test(first) && OCTAL.test(second) && third !== undefined && OCTAL.test(third)) {
        this.i += 2;
        return `\\u{${parseInt(first + second + third, 8).toString(16)}}`;
      }
      this.i += 1;
      const number = Number(first + second);
      this.maxBackref = Math.max(this.maxBackref, number);
      return `\\k<_g${number}>`;
    }
    const number = Number(first);
    this.maxBackref = Math.max(this.maxBackref, number);
    return `\\k<_g${number}>`;
  }

  wordBoundary(inside) {
    const w = `[${this.word}]`;
    return inside
      ? `(?:(?<=${w})(?!${w})|(?<!${w})(?=${w}))`
      : `(?:(?<=${w})(?=${w})|(?<!${w})(?!${w}))`;
  }

  readHexEscape(width) {
    const hex = this.src.slice(this.i, this.i + width);
    if (hex.length !== width || !/^[0-9a-fA-F]+$/.test(hex)) this.error('incomplete escape');
    this.i += width;
    const cp = parseInt(hex, 16);
    if (cp > 0x10ffff) this.error('invalid escape');
    return `\\u{${cp.toString(16)}}`;
  }

  /** Up to three octal digits, counting the one already consumed. */
  readOctalEscape(first) {
    let digits = first;
    while (digits.length < 3 && OCTAL.test(this.src[this.i] ?? '')) {
      digits += this.src[this.i];
      this.i++;
    }
    return `\\u{${(parseInt(digits, 8) & 0xff).toString(16)}}`;
  }

  /** \N{LATIN SMALL LETTER A} needs a Unicode name table the runtime does not expose. */
  readNamedEscape() {
    this.error('unsupported named unicode escape');
  }
}

const cache = new Map();

/**
 * Compile a Python pattern to a RegExp, as `re.compile` would.
 * @param {string} pattern
 * @returns {RegExp}
 * @throws {PyReError} where Python's re.error would escape to the interpreter
 */
export function compilePattern(pattern) {
  const cached = cache.get(pattern);
  if (cached !== undefined) {
    if (cached instanceof PyReError) throw cached;
    return cached;
  }
  let result;
  try {
    const { source, flags } = new Translator(pattern).translate();
    result = new RegExp(source, flags);
  } catch (err) {
    result = err instanceof PyReError ? err : new PyReError(String(err.message));
    cache.set(pattern, result);
    throw result;
  }
  cache.set(pattern, result);
  return result;
}

/**
 * re.search(pattern, string) as a boolean.
 * @param {string} pattern
 * @param {string} text
 * @returns {boolean}
 */
export function reSearch(pattern, text) {
  return compilePattern(pattern).test(text);
}

