// jsonschema's exception types and, crucially, best_match -- the rule that picks the
// ONE error the program prints out of everything a schema produced.
//
// Empirically (and matching jsonschema's implementation):
//
//   best = max(errors, key=relevance)          # ties keep the first error produced
//   while best.context: best = min(best.context, key=relevance)
//
//   relevance(e) = (-len(e.path), e.path, e.validator not in WEAK, e.validator in STRONG)
//
// So at the top level a *shallower* error wins, and among equally deep siblings the
// *later* path wins; anyOf/oneOf are "weak" and lose to any other keyword. Descending
// into an anyOf/oneOf's collected sub-errors inverts all of that (min instead of max),
// which is why the deepest sub-error surfaces there.

import { pyRepr } from '../python/repr.mjs';
import { PyError } from '../python/exceptions.mjs';

const WEAK_MATCHES = new Set(['anyOf', 'oneOf']);
const STRONG_MATCHES = new Set();

export class ValidationError extends Error {
  /**
   * @param {string} message the text the reference program prints
   * @param {object} [opts]
   * @param {string|null} [opts.validator] the keyword that produced this error
   * @param {ValidationError[]} [opts.context] sub-errors, as anyOf/oneOf collect them
   */
  constructor(message, { validator = null, validatorValue = null, instance = null,
    schema = null, context = [], path = [], schemaPath = [] } = {}) {
    super(message);
    this.pyMessage = message;
    this.validator = validator;
    this.validatorValue = validatorValue;
    this.instance = instance;
    this.schema = schema;
    this.context = context;
    /** Instance path from the root: object keys as strings, array indices as numbers. */
    this.path = path;
    this.schemaPath = schemaPath;
    this.validatorSet = validator !== null;
  }

  /** jsonschema's ValidationError._set: fill in only what is still unset. */
  fill({ validator, validatorValue, instance, schema }) {
    if (!this.validatorSet) {
      this.validator = validator;
      this.validatorSet = true;
    }
    if (this.validatorValue === null) this.validatorValue = validatorValue;
    if (this.instance === null) this.instance = instance;
    if (this.schema === null) this.schema = schema;
    return this;
  }
}

export class SchemaError extends PyError {
  constructor(message) {
    super('jsonschema.exceptions.SchemaError', message);
    this.pyMessage = message;
  }
}

/** A $ref that cannot be resolved; escapes to the interpreter like Python's. */
export class Unresolvable extends PyError {
  constructor(ref) {
    super('referencing.exceptions.Unresolvable', `Unresolvable: ${ref}`);
    this.ref = ref;
  }
}

export class PointerToNowhere extends PyError {
  constructor(ref, resource) {
    super('referencing.exceptions.PointerToNowhere', `${ref} does not exist within ${resource}`);
  }
}

/** Python compares str by code point; JS `<` compares UTF-16 units. */
function compareStrings(a, b) {
  if (a === b) return 0;
  const ai = [...a];
  const bi = [...b];
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i++) {
    const x = ai[i].codePointAt(0);
    const y = bi[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  return ai.length === bi.length ? 0 : ai.length < bi.length ? -1 : 1;
}

/**
 * Python's list comparison for instance paths. Only ever called on equal-length paths
 * (length is compared first), and at a given position two errors on the same instance
 * always carry the same key type, so int-vs-str never arises.
 */
function comparePath(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a[i] === b[i]) continue;
    if (typeof a[i] === 'string' && typeof b[i] === 'string') return compareStrings(a[i], b[i]);
    return a[i] < b[i] ? -1 : 1;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

/** Three-way comparison of two errors by jsonschema's relevance key. */
function compareRelevance(a, b) {
  // -len(path): fewer path segments sorts higher.
  if (a.path.length !== b.path.length) return a.path.length < b.path.length ? 1 : -1;
  const byPath = comparePath(a.path, b.path);
  if (byPath !== 0) return byPath;
  const aWeak = WEAK_MATCHES.has(a.validator);
  const bWeak = WEAK_MATCHES.has(b.validator);
  if (aWeak !== bWeak) return aWeak ? -1 : 1; // "not in weak" -> True sorts higher
  const aStrong = STRONG_MATCHES.has(a.validator);
  const bStrong = STRONG_MATCHES.has(b.validator);
  if (aStrong !== bStrong) return aStrong ? 1 : -1;
  return 0;
}

/** Python's max(): the first of the maximal elements. */
function maxByRelevance(errors) {
  let best = errors[0];
  for (const error of errors.slice(1)) {
    if (compareRelevance(error, best) > 0) best = error;
  }
  return best;
}

/** Python's heapq.nsmallest(1)/min(): the first of the minimal elements. */
function minByRelevance(errors) {
  let best = errors[0];
  for (const error of errors.slice(1)) {
    if (compareRelevance(error, best) < 0) best = error;
  }
  return best;
}

/**
 * jsonschema's best_match.
 * @param {Iterable<ValidationError>} errors
 * @returns {ValidationError|null}
 */
export function bestMatch(errors) {
  const all = [...errors];
  if (!all.length) return null;
  let best = maxByRelevance(all);
  while (best.context.length) best = minByRelevance(best.context);
  return best;
}

/** extras_msg(): the ("'a', 'b'", "were") pair several messages interpolate. */
export function extrasMsg(extras) {
  const list = [...extras];
  return [list.map(pyRepr).join(', '), list.length === 1 ? 'was' : 'were'];
}

