// type, enum and const.

import { pyRepr } from '../../python/repr.mjs';
import { isList } from '../../python/value.mjs';
import { ValidationError } from '../exceptions.mjs';
import { equal } from '../equality.mjs';

/** ensure_list(): a bare string becomes a one-element list. */
const ensureList = (value) => (isList(value) ? value : [value]);

export function* type(validator, types, instance) {
  const wanted = ensureList(types);
  if (wanted.some((t) => validator.isType(instance, t))) return;
  const reprs = wanted.map(pyRepr).join(', ');
  yield new ValidationError(`${pyRepr(instance)} is not of type ${reprs}`);
}

export function* enum_(validator, enums, instance) {
  if (enums.every((each) => !equal(each, instance))) {
    yield new ValidationError(`${pyRepr(instance)} is not one of ${pyRepr(enums)}`);
  }
}

export function* const_(validator, constValue, instance) {
  if (!equal(constValue, instance)) {
    yield new ValidationError(`${pyRepr(constValue)} was expected`);
  }
}

