// minimum, maximum, exclusiveMinimum, exclusiveMaximum, multipleOf.
//
// Booleans are not numbers here (jsonschema's type checker excludes them), and the
// int/float split is visible in the messages: {"multipleOf": 2.0} reports "2.0".

import { pyRepr } from '../../python/repr.mjs';
import { isFloat, isTruthyNumber, numGe, numGt, numLe, numLt, pyMod, floatToInt, trueDivide } from '../../python/value.mjs';
import { ValidationError } from '../exceptions.mjs';

export function* minimum(validator, minimumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (numLt(instance, minimumValue)) {
    yield new ValidationError(
      `${pyRepr(instance)} is less than the minimum of ${pyRepr(minimumValue)}`,
    );
  }
}

export function* maximum(validator, maximumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (numGt(instance, maximumValue)) {
    yield new ValidationError(
      `${pyRepr(instance)} is greater than the maximum of ${pyRepr(maximumValue)}`,
    );
  }
}

export function* exclusiveMinimum(validator, minimumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (numLe(instance, minimumValue)) {
    yield new ValidationError(
      `${pyRepr(instance)} is less than or equal to the minimum of ${pyRepr(minimumValue)}`,
    );
  }
}

export function* exclusiveMaximum(validator, maximumValue, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (numGe(instance, maximumValue)) {
    yield new ValidationError(
      `${pyRepr(instance)} is greater than or equal to the maximum of ${pyRepr(maximumValue)}`,
    );
  }
}

export function* multipleOf(validator, divisor, instance) {
  if (!validator.isType(instance, 'number')) return;
  let failed;
  if (isFloat(divisor)) {
    // A float divisor goes through true division; anything that cannot be turned into
    // an int (inf, nan) counts as a failure, and Python raises for a zero divisor.
    const quotient = trueDivide(instance, divisor);
    try {
      failed = floatToInt(quotient) !== BigInt(Math.trunc(quotient)) || !Number.isInteger(quotient);
    } catch {
      failed = true;
    }
  } else {
    failed = isTruthyNumber(pyMod(instance, divisor));
  }
  if (failed) {
    yield new ValidationError(`${pyRepr(instance)} is not a multiple of ${pyRepr(divisor)}`);
  }
}

