// Predicates and arithmetic for the Python value model (see ./repr.mjs for the model).
//
// The point of the model is that Python's int/float distinction is observable: `1` and
// `1.0` validate the same but print differently, ints are arbitrary precision, and
// `int % int` is exact while `float % float` is not. int -> BigInt, float -> number.

import { PyArithmeticError } from './exceptions.mjs';

export const isNone = (v) => v === null;export const isBool = (v) => v === true || v === false;
export const isInt = (v) => typeof v === 'bigint';
export const isFloat = (v) => typeof v === 'number';
export const isStr = (v) => typeof v === 'string';
export const isList = (v) => Array.isArray(v);
export const isDict = (v) => v instanceof Map;
/** True for Python numbers only -- bool is a subclass of int in Python, so callers
 *  that must exclude booleans check isBool separately (jsonschema does exactly that). */
export const isNumeric = (v) => typeof v === 'bigint' || typeof v === 'number';

/** Number of code points, i.e. Python's len() for a str. */
export function strLen(s) {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

const UNORDERED = NaN;

/**
 * Python's three-way numeric comparison, exact across the int/float boundary
 * (Python never rounds an int to compare it with a float).
 * @returns {number} -1, 0, 1, or NaN when either side is nan (all comparisons false)
 */
export function numCmp(a, b) {
  const aBig = typeof a === 'bigint';
  const bBig = typeof b === 'bigint';
  if (aBig && bBig) return a < b ? -1 : a > b ? 1 : 0;
  if (!aBig && !bBig) {
    if (Number.isNaN(a) || Number.isNaN(b)) return UNORDERED;
    return a < b ? -1 : a > b ? 1 : 0;
  }
  return aBig ? cmpIntFloat(a, b) : -cmpIntFloat(b, a);
}

function cmpIntFloat(i, f) {
  if (Number.isNaN(f)) return UNORDERED;
  if (f === Infinity) return -1;
  if (f === -Infinity) return 1;
  // floor(f) is an exact integer double, so BigInt() of it is lossless.
  const floor = Math.floor(f);
  const asBig = BigInt(floor);
  if (i < asBig) return -1;
  if (i > asBig) return 1;
  return f === floor ? 0 : -1; // i === floor(f) < f
}

export const numLt = (a, b) => numCmp(a, b) === -1;
export const numGt = (a, b) => numCmp(a, b) === 1;
export const numEq = (a, b) => numCmp(a, b) === 0;
export const numLe = (a, b) => { const c = numCmp(a, b); return c === -1 || c === 0; };
export const numGe = (a, b) => { const c = numCmp(a, b); return c === 1 || c === 0; };

/** Python's `int(x)` on a float: truncates toward zero; blows up on inf/nan. */
export function floatToInt(x) {
  if (Number.isNaN(x)) throw new PyArithmeticError('ValueError', 'cannot convert float NaN to integer');
  if (!Number.isFinite(x)) throw new PyArithmeticError('OverflowError', 'cannot convert float infinity to integer');
  return BigInt(Math.trunc(x));
}

/** Python's `int / float` -> float, including the OverflowError for huge ints. */
export function trueDivide(a, b) {
  const af = toFloat(a);
  const bf = toFloat(b);
  return af / bf;
}

/** Python's float(x); an int too large for a double raises OverflowError. */
export function toFloat(v) {
  if (typeof v === 'number') return v;
  const f = Number(v);
  if (!Number.isFinite(f)) {
    throw new PyArithmeticError('OverflowError', 'int too large to convert to float');
  }
  return f;
}

/**
 * Python's `%`. Only its zero-ness is ever consulted by jsonschema, but the
 * sign convention (result takes the divisor's sign) is Python's, not JS's.
 */
export function pyMod(a, b) {
  if (typeof a === 'bigint' && typeof b === 'bigint') {
    if (b === 0n) throw new PyArithmeticError('ZeroDivisionError', 'integer modulo by zero');
    const r = a % b;
    return r !== 0n && (r < 0n) !== (b < 0n) ? r + b : r;
  }
  const af = toFloat(a);
  const bf = toFloat(b);
  if (bf === 0) throw new PyArithmeticError('ZeroDivisionError', 'float modulo');
  const r = af % bf;
  return r !== 0 && r < 0 !== bf < 0 ? r + bf : r;
}

/** Truthiness of a Python number, as `if failed:` would see it.
 *  Note nan is truthy and -0.0 is falsey, which `!== 0` gets right for both. */
export const isTruthyNumber = (v) => (typeof v === 'bigint' ? v !== 0n : v !== 0);

