// minLength, maxLength, pattern and format.
//
// Lengths count Unicode code points (Python's len), not UTF-16 units, so an astral
// emoji is one character. `format` is only asserted when a format checker is installed,
// and jsonschema.validate() installs none -- so it never fails here.

import { pyRepr } from '../../python/repr.mjs';
import { strLen } from '../../python/value.mjs';
import { reSearch } from '../../python/re.mjs';
import { ValidationError } from '../exceptions.mjs';

export function* minLength(validator, limit, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (strLen(instance) < Number(limit)) {
    const message = Number(limit) === 1 ? 'should be non-empty' : 'is too short';
    yield new ValidationError(`${pyRepr(instance)} ${message}`);
  }
}

export function* maxLength(validator, limit, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (strLen(instance) > Number(limit)) {
    const message = Number(limit) === 0 ? 'is expected to be empty' : 'is too long';
    yield new ValidationError(`${pyRepr(instance)} ${message}`);
  }
}

export function* pattern(validator, patrn, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (!reSearch(patrn, instance)) {
    yield new ValidationError(`${pyRepr(instance)} does not match ${pyRepr(patrn)}`);
  }
}

export function* format(validator, formatName, instance) {
  if (validator.formatChecker === null) return;
  if (!validator.formatChecker.check(instance, formatName)) {
    yield new ValidationError(`${pyRepr(instance)} is not a ${pyRepr(formatName)}`);
  }
}

