// Array keywords: prefixItems, items, additionalItems, contains, minItems, maxItems,
// uniqueItems.
//
// In 2020-12 `items` applies to everything past `prefixItems`, and `items: false`
// produces a counting message ("Expected at most 1 item but found 1 extra: 2") whose
// singular/plural forms and value rendering are both load-bearing.

import { pyRepr } from '../../python/repr.mjs';
import { isDict } from '../../python/value.mjs';
import { ValidationError } from '../exceptions.mjs';
import { uniq } from '../equality.mjs';

export function* prefixItems(validator, prefix, instance) {
  if (!validator.isType(instance, 'array')) return;
  const n = Math.min(prefix.length, instance.length);
  for (let index = 0; index < n; index++) {
    yield* validator.descend(instance[index], prefix[index], { path: index, schemaPath: index });
  }
}

export function* items(validator, itemsSchema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const prefixSchema = isDict(schema) ? schema.get('prefixItems') : undefined;
  const prefix = Array.isArray(prefixSchema) ? prefixSchema.length : 0;
  const total = instance.length;
  const extra = total - prefix;
  if (extra <= 0) return;
  if (itemsSchema === false) {
    // A single extra item is reported bare; several are reported as a list.
    const rest = extra !== 1 ? instance.slice(prefix) : instance[prefix];
    const noun = prefix !== 1 ? 'items' : 'item';
    yield new ValidationError(
      `Expected at most ${prefix} ${noun} but found ${extra} extra: ${pyRepr(rest)}`,
    );
    return;
  }
  for (let index = prefix; index < total; index++) {
    yield* validator.descend(instance[index], itemsSchema, { path: index });
  }
}

/** Draft 3-2019: `items` may be a tuple of schemas, with additionalItems for the rest. */
export function* itemsDraft2019(validator, itemsSchema, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (Array.isArray(itemsSchema)) {
    const n = Math.min(itemsSchema.length, instance.length);
    for (let index = 0; index < n; index++) {
      yield* validator.descend(instance[index], itemsSchema[index], { path: index, schemaPath: index });
    }
    return;
  }
  for (const [index, item] of instance.entries()) {
    yield* validator.descend(item, itemsSchema, { path: index });
  }
}

export function* additionalItems(validator, aI, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const itemsSchema = isDict(schema) ? schema.get('items') : undefined;
  if (!Array.isArray(itemsSchema)) return;
  const start = itemsSchema.length;
  if (validator.isType(aI, 'object') || aI === true) {
    for (let index = start; index < instance.length; index++) {
      yield* validator.descend(instance[index], aI, { path: index });
    }
  } else if (aI === false && instance.length > start) {
    const noun = start === 1 ? 'item' : 'items';
    yield new ValidationError(
      `Additional items are not allowed (${pyRepr(instance.slice(start))} ${instance.length - start === 1 ? 'was' : 'were'} unexpected)`.replace(
        'ITEMS', noun,
      ),
    );
  }
}

export function* contains(validator, containsSchema, instance, schema) {
  if (!validator.isType(instance, 'array')) return;
  const minContains = isDict(schema) && schema.has('minContains') ? Number(schema.get('minContains')) : 1;
  const maxContains = isDict(schema) && schema.has('maxContains')
    ? Number(schema.get('maxContains'))
    : instance.length;

  let matches = 0;
  for (const each of instance) {
    if (validator.evolve({ schema: containsSchema }).isValid(each)) {
      matches++;
      if (matches > maxContains) {
        yield new ValidationError(
          `Too many items match the given schema (expected at most ${maxContains})`,
        );
        return;
      }
    }
  }
  if (matches < minContains) {
    if (!matches) {
      yield new ValidationError(
        `${pyRepr(instance)} does not contain items matching the given schema`,
      );
    } else {
      yield new ValidationError(
        `Too few items match the given schema (expected at least ${minContains} but only ${matches} matched)`,
      );
    }
  }
}

/** Draft 6-2019 contains: no min/maxContains, so any match is enough. */
export function* containsDraft2019(validator, containsSchema, instance) {
  if (!validator.isType(instance, 'array')) return;
  const matched = instance.some((each) => validator.evolve({ schema: containsSchema }).isValid(each));
  if (!matched) {
    yield new ValidationError(
      `${pyRepr(instance)} does not contain items matching the given schema`,
    );
  }
}

export function* minItems(validator, limit, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (instance.length < Number(limit)) {
    const message = Number(limit) === 1 ? 'should be non-empty' : 'is too short';
    yield new ValidationError(`${pyRepr(instance)} ${message}`);
  }
}

export function* maxItems(validator, limit, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (instance.length > Number(limit)) {
    const message = Number(limit) === 0 ? 'is expected to be empty' : 'is too long';
    yield new ValidationError(`${pyRepr(instance)} ${message}`);
  }
}

export function* uniqueItems(validator, unique, instance) {
  if (unique && validator.isType(instance, 'array') && !uniq(instance)) {
    yield new ValidationError(`${pyRepr(instance)} has non-unique elements`);
  }
}

