      const cy = y[i].codePointAt(0);
      if (cx !== cy) return cx - cy;
    }
    return x.length - y.length;
  });
}

export function* properties(validator, props, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, subschema] of props) {
    if (instance.has(property)) {
      yield* validator.descend(instance.get(property), subschema, {
        path: property,
        schemaPath: property,
      });
    }
  }
}

export function* patternProperties(validator, patterns, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [pattern, subschema] of patterns) {
    for (const [key, value] of instance) {
      if (reSearch(pattern, key)) {
        yield* validator.descend(value, subschema, { path: key, schemaPath: pattern });
      }
    }
  }
}

export function* additionalProperties(validator, aP, instance, schema) {
  if (!validator.isType(instance, 'object')) return;
  const extras = [...findAdditionalProperties(instance, schema)];
  if (validator.isType(aP, 'object') || validator.isType(aP, 'boolean')) {
    for (const extra of extras) {
      yield* validator.descend(instance.get(extra), aP, { path: extra });
    }
  } else if (!aP && extras.length) {
    if (schema.has('patternProperties')) {
      const verb = extras.length === 1 ? 'does' : 'do';
      const joined = sortedByStr(extras).map(pyRepr).join(', ');
      const patterns = sortedByStr([...schema.get('patternProperties').keys()]).map(pyRepr).join(', ');
      yield new ValidationError(`${joined} ${verb} not match any of the regexes: ${patterns}`);
    } else {
      const [joined, verb] = extrasMsg(sortedByStr(extras));
      yield new ValidationError(`Additional properties are not allowed (${joined} ${verb} unexpected)`);
    }
  }
}

export function* required(validator, requiredProperties, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of requiredProperties) {
    if (!instance.has(property)) {
      yield new ValidationError(`${pyRepr(property)} is a required property`);
    }
  }
}

export function* dependentRequired(validator, dependencies, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, dependency] of dependencies) {
    if (!instance.has(property)) continue;
    for (const each of dependency) {
      if (!instance.has(each)) {
        yield new ValidationError(`${pyRepr(each)} is a dependency of ${pyRepr(property)}`);
      }
    }
  }
}

export function* dependentSchemas(validator, dependencies, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, dependency] of dependencies) {
    if (!instance.has(property)) continue;
    yield* validator.descend(instance, dependency, { schemaPath: property });
  }
}

/** Draft 3-2019 `dependencies`: a list means required, a schema means dependentSchemas. */
export function* dependencies(validator, deps, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const [property, dependency] of deps) {
    if (!instance.has(property)) continue;
    if (isList(dependency) || isStr(dependency)) {
      const each = isStr(dependency) ? [dependency] : dependency;
      for (const item of each) {
        if (!instance.has(item)) {
          yield new ValidationError(`${pyRepr(item)} is a dependency of ${pyRepr(property)}`);
        }
      }
    } else {
      yield* validator.descend(instance, dependency, { schemaPath: property });
    }
  }
}

export function* propertyNames(validator, subschema, instance) {
  if (!validator.isType(instance, 'object')) return;
  for (const property of instance.keys()) {
    // No path is appended: the error's instance becomes the property name itself.
    yield* validator.descend(property, subschema);
  }
}

export function* minProperties(validator, limit, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (instance.size < Number(limit)) {
    const message = Number(limit) === 1 ? 'should be non-empty' : 'does not have enough properties';
    yield new ValidationError(`${pyRepr(instance)} ${message}`);
  }
}

export function* maxProperties(validator, limit, instance) {
  if (!validator.isType(instance, 'object')) return;
  if (instance.size > Number(limit)) {
    const message = Number(limit) === 0 ? 'is expected to be empty' : 'has too many properties';
    yield new ValidationError(`${pyRepr(instance)} ${message}`);
  }
}

export { sortedByStr };

