// The applicators: allOf, anyOf, oneOf, not, if/then/else.
//
// anyOf and oneOf attach every branch's errors as `context` on a single error, which is
// what best_match later descends into. oneOf's "valid under each of" message names the
// extra matching branches in index order and then repeats the first match last -- a
// consequence of how jsonschema consumes its enumerate() twice.

import { pyRepr } from '../../python/repr.mjs';
import { ValidationError } from '../exceptions.mjs';

export function* allOf(validator, subschemas, instance) {
  for (const [index, subschema] of subschemas.entries()) {
    yield* validator.descend(instance, subschema, { schemaPath: index });
  }
}

export function* anyOf(validator, subschemas, instance) {
  const allErrors = [];
  for (const [index, subschema] of subschemas.entries()) {
    const errors = [...validator.descend(instance, subschema, { schemaPath: index })];
    if (!errors.length) return;
    allErrors.push(...errors);
  }
  yield new ValidationError(
    `${pyRepr(instance)} is not valid under any of the given schemas`,
    { context: allErrors },
  );
}

export function* oneOf(validator, subschemas, instance) {
  const allErrors = [];
  let firstValidIndex = -1;
  for (const [index, subschema] of subschemas.entries()) {
    const errors = [...validator.descend(instance, subschema, { schemaPath: index })];
    if (!errors.length) {
      firstValidIndex = index;
      break;
    }
    allErrors.push(...errors);
  }
  if (firstValidIndex === -1) {
    yield new ValidationError(
      `${pyRepr(instance)} is not valid under any of the given schemas`,
      { context: allErrors },
    );
    return;
  }

  // The generator resumes after the first match, so only later branches are re-checked.
  const moreMatches = [];
  for (let index = firstValidIndex + 1; index < subschemas.length; index++) {
    if (validator.evolve({ schema: subschemas[index] }).isValid(instance)) moreMatches.push(index);
  }
  if (moreMatches.length) {
    const reprs = moreMatches.map((index) => pyRepr(subschemas[index])).join(', ');
    yield new ValidationError(
      `${pyRepr(instance)} is valid under each of ${reprs}, ${pyRepr(subschemas[firstValidIndex])}`,
    );
  }
}

export function* not_(validator, notSchema, instance) {
  if (validator.evolve({ schema: notSchema }).isValid(instance)) {
    yield new ValidationError(`${pyRepr(instance)} should not be valid under ${pyRepr(notSchema)}`);
  }
}

export function* if_(validator, ifSchema, instance, schema) {
  if (validator.evolve({ schema: ifSchema }).isValid(instance)) {
    if (schema.has('then')) {
      yield* validator.descend(instance, schema.get('then'), { schemaPath: 'then' });
    }
  } else if (schema.has('else')) {
    yield* validator.descend(instance, schema.get('else'), { schemaPath: 'else' });
  }
}

